/**
 * Fabrique de statics — server side. A run for a client: templates chosen →
 * context (the client's cached HQ brief, what the templates say, the reviews
 * pasted by the consultant, past feedback) → copies proposed by Sonnet and
 * validated by the consultant → images generated by batches of 4 at fal
 * (Nano Banana 2 edit, the template picture and ≤ 2 brand assets as
 * references), ≤ 12 per HTTP pass → CreativeAsset rows (origin "factory") and
 * a copy of each file in the client's Drive « Créas/Fabrique <date> <kind>/ »
 * → feedback at three levels (visual, template, run) journaled in HQ.
 * The pure parts (prompts, parsers, plan, state machine) are in ./copy.ts.
 */

import type { CreativeAsset, CreativeFeedback, CreativeTemplate, FactoryCopy, FactoryRun } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { parseLooseJson, relayComplete } from "@/lib/relay-chat";
import { recordAiUsage } from "@/lib/ai-usage";
import { brandBriefFromHq } from "@/lib/mo/brief";
import { isHqContextFresh } from "@/lib/hq-client-context";
import { IMAGE_RATIOS, isFalModel, relayFalImage, relayFalModels } from "@/lib/studio";
import { assetView, type AssetView } from "@/lib/studio-assets";
import { checkGeneration, readQuotas, spentToday } from "@/lib/quotas";
import { ensureClientSubfolder, ensureSubfolder, uploadToFolder } from "@/lib/clients/drive";
import { appendHqJournal } from "@/lib/hq-journal";
import { mediaFileDataUri } from "@/lib/creas/media";
import { buildCopyPrompt } from "@/lib/creas/templates";
import { DEFAULT_FACTORY_ENGINE, DEFAULT_PER_TEMPLATE, FACTORY_KINDS, MAX_RUN_IMAGES, PARALLEL_BATCHES, PASS_SIZE, parseAnalysis, parseIdList, parseSettings, parseSources, type FactoryCopyView, type FactoryKind, type FactoryRunView, type FactorySettings, type FeedbackLevel, type FeedbackView, type RunStatus } from "@/lib/creas/model";
import { contextForRun } from "@/lib/creas/context";
import { feedbackLines, variationReference } from "@/lib/creas/copy";
import { assembleContext, buildCopyProposalPrompt, buildFactoryImagePrompt, canTransition, estimateUsd, factoryFileName, factoryFolderName, parseCopyProposals, passPlan, planSlots, remainingOf, statusAfterPass, type CopyTemplateInput } from "@/lib/creas/copy";

export interface FactoryClient { id: string; name: string; hqSlug: string | null }
export interface FactoryUser { id: string; email: string | null; role: string; name: string }

const MODEL = (process.env.AI_CREAS_MODEL as "sonnet" | "opus" | undefined) ?? "sonnet";
export const RUN_ID_RE = /^[a-z0-9]{10,40}$/i;

// ── Client helpers ─────────────────────────────────────────────────────────

/** The dashboards of a client: the one on its registry row, then those on its ad accounts. */
export async function clientDashboardIds(client: Pick<FactoryClient, "id">): Promise<string[]> {
  const ac = await prisma.alertClient.findUnique({ where: { id: client.id }, select: { dashboardId: true, accountsJson: true } });
  if (!ac) return [];
  let accs: Array<{ platform: string; accountId: string }> = [];
  try { accs = JSON.parse(ac.accountsJson); } catch { accs = []; }
  const meta = accs.filter((a) => a.platform === "meta").map((a) => a.accountId.replace(/^act_/, ""));
  const google = accs.filter((a) => a.platform === "google").map((a) => a.accountId.replace(/-/g, ""));
  const rows = await prisma.dashboard.findMany({ where: { OR: [...(meta.length ? [{ metaAccountId: { in: meta } }] : []), ...(google.length ? [{ googleCustomerId: { in: google } }] : [])] }, select: { id: true }, orderBy: { createdAt: "asc" } });
  return Array.from(new Set([ac.dashboardId, ...rows.map((r) => r.id)].filter((v): v is string => !!v)));
}

/** The brand brief of the client from the HQ context cached on its dashboards (no HQ call). */
export async function clientBrandBrief(client: Pick<FactoryClient, "id">): Promise<string> {
  const ids = await clientDashboardIds(client);
  if (!ids.length) return "";
  const rows = await prisma.dashboard.findMany({ where: { id: { in: ids }, hqContextMd: { not: null } }, select: { hqContextMd: true, hqContextAt: true }, orderBy: { hqContextAt: "desc" }, take: 3 });
  const fresh = rows.find((d) => isHqContextFresh(d)) ?? rows[0];
  return brandBriefFromHq(fresh?.hqContextMd, 1800);
}

/** The HQ project of the client (its own slug, else its dashboards'), or null. */
export async function clientHqProject(client: FactoryClient): Promise<string | null> {
  if (client.hqSlug) return client.hqSlug;
  const ids = await clientDashboardIds(client);
  if (!ids.length) return null;
  const d = await prisma.dashboard.findFirst({ where: { id: { in: ids }, hqSlug: { not: null } }, select: { hqSlug: true } });
  return d?.hqSlug ?? null;
}

// ── Views ──────────────────────────────────────────────────────────────────

export function copyView(c: FactoryCopy): FactoryCopyView {
  return { id: c.id, runId: c.runId, templateId: c.templateId, order: c.order, headline: c.headline, subline: c.subline, cta: c.cta, angle: c.angle, persona: c.persona, voiceSource: c.voiceSource, status: c.status === "approved" || c.status === "rejected" ? c.status : "proposed", editedByHuman: c.editedByHuman };
}

export function runView(r: FactoryRun, copies: FactoryCopy[] = []): FactoryRunView {
  const settings = parseSettings(r.settingsJson);
  return {
    id: r.id, clientId: r.alertClientId, clientName: r.clientName, kind: (FACTORY_KINDS as readonly string[]).includes(r.kind) ? (r.kind as FactoryKind) : "offer", status: r.status as RunStatus,
    templateIds: parseIdList(r.templateIdsJson), contextMd: r.contextMd, sources: parseSources(r.sourcesJson), settings,
    estimatedUsd: r.estimatedUsd, costUsd: r.costUsd, generated: r.generated, kept: r.kept, cut: r.cut, remaining: remainingOf(settings),
    driveLink: r.driveLink, createdByName: r.createdByName, createdAt: r.createdAt.toISOString(), updatedAt: r.updatedAt.toISOString(),
    copies: copies.map(copyView),
  };
}

export const feedbackView = (f: CreativeFeedback): FeedbackView => ({ id: f.id, level: f.level as FeedbackLevel, clientId: f.alertClientId, assetId: f.assetId, templateId: f.templateId, runId: f.runId, text: f.text, createdByName: f.createdByName, createdAt: f.createdAt.toISOString() });

export async function loadRun(id: string): Promise<FactoryRun | null> {
  if (!RUN_ID_RE.test(id)) return null;
  return prisma.factoryRun.findUnique({ where: { id } });
}

export const runCopies = (runId: string) => prisma.factoryCopy.findMany({ where: { runId }, orderBy: { order: "asc" } });
export const runAssets = (runId: string) => prisma.creativeAsset.findMany({ where: { factoryRunId: runId, deletedAt: null }, orderBy: { createdAt: "asc" } });

export async function listRuns(clientId: string, take = 30): Promise<FactoryRunView[]> {
  const rows = await prisma.factoryRun.findMany({ where: { alertClientId: clientId }, orderBy: { createdAt: "desc" }, take });
  return rows.map((r) => runView(r));
}

const templateInput = (t: CreativeTemplate): CopyTemplateInput => ({ id: t.id, name: t.name, brand: t.brand, source: t.source, analysis: parseAnalysis(t.analysisJson) });

export async function loadRunTemplates(ids: string[]): Promise<CreativeTemplate[]> {
  if (!ids.length) return [];
  const rows = await prisma.creativeTemplate.findMany({ where: { id: { in: ids }, deletedAt: null } });
  const byId = new Map(rows.map((r) => [r.id, r]));
  return ids.map((id) => byId.get(id)).filter((r): r is CreativeTemplate => !!r);
}

// ── Create a run and propose the copies ────────────────────────────────────

export interface CreateRunInput { kind: FactoryKind; templateIds: string[]; perTemplate?: number; reviews?: string; instructions?: string; persona?: string; season?: string }

/**
 * A new run in « copy_review »: the context is assembled and frozen, the
 * model proposes `perTemplate` copies per template. When the model fails the
 * run still exists (status copy_review, no copy, the error in settings) so
 * the consultant can ask again.
 */
export async function createRun(client: FactoryClient, user: FactoryUser, input: CreateRunInput): Promise<{ run: FactoryRunView; templates: CreativeTemplate[]; error?: string }> {
  const templates = (await loadRunTemplates(input.templateIds.slice(0, 12))).filter((t) => !!t.file);
  if (!templates.length) throw new FactoryError(400, "Choisissez au moins un template avec une image.");
  // The client's context document (HQ brief and files, warehouse winners, comments, client-level feedback: lib/creas/context.ts),
  // then what is specific to this run: the feedback on the chosen templates.
  // Plus the client- and run-level feedback written since the document was saved (« pas de -50 % » on the last fabrique is read by the next one).
  const clientDoc = await contextForRun(client);
  const feedback = await prisma.creativeFeedback.findMany({
    where: { OR: [{ templateId: { in: templates.map((t) => t.id) }, level: "template" }, { alertClientId: client.id, level: { in: ["client", "run"] }, createdAt: { gt: clientDoc.since } }] },
    orderBy: { createdAt: "desc" }, take: 16, select: { level: true, text: true },
  });
  const ctx = assembleContext({ clientName: client.name, brief: "", client: clientDoc, templates: templates.map(templateInput), reviews: input.reviews ?? "", feedback, instructions: input.instructions });
  const perTemplate = Math.min(12, Math.max(1, Math.round(input.perTemplate ?? DEFAULT_PER_TEMPLATE)));
  const settings: FactorySettings = { n: 0, engine: DEFAULT_FACTORY_ENGINE, ratio: "1:1", textless: false, perTemplate, attempted: 0, failed: 0, ...(input.persona ? { persona: input.persona } : {}), ...(input.season ? { season: input.season } : {}), ...(input.instructions ? { instructions: input.instructions } : {}) };
  const row = await prisma.factoryRun.create({ data: {
    alertClientId: client.id, clientName: client.name, kind: input.kind, status: "draft", templateIdsJson: JSON.stringify(templates.map((t) => t.id)),
    contextMd: ctx.md, sourcesJson: JSON.stringify(ctx.sources), settingsJson: JSON.stringify(settings), createdById: user.id, createdByName: user.name,
  } });
  const { copies, error } = await proposeCopies(row, templates, user);
  const updated = await prisma.factoryRun.update({ where: { id: row.id }, data: { status: "copy_review", ...(error ? { settingsJson: JSON.stringify({ ...settings, error }) } : {}) } });
  return { run: runView(updated, copies), templates, ...(error ? { error } : {}) };
}

export interface VariationInput { assetIds?: string[]; perTemplate?: number; persona?: string; season?: string; instructions?: string }

/**
 * Variations of the kept visuals of a run: a new run (kind « variation »,
 * parentRunId) on the same templates, whose copies go through validation
 * again; each visual is then made with the kept one as reference 1.
 */
export async function createVariationRun(parent: FactoryRun, client: FactoryClient, user: FactoryUser, input: VariationInput): Promise<{ run: FactoryRunView; templates: CreativeTemplate[]; error?: string }> {
  const wanted = (input.assetIds ?? []).filter((id) => RUN_ID_RE.test(id));
  const kept = await prisma.creativeAsset.findMany({
    where: { factoryRunId: parent.id, deletedAt: null, status: "completed", templateId: { not: null }, ...(wanted.length ? { id: { in: wanted } } : { feedback: "keep" }) },
    orderBy: { createdAt: "asc" }, take: 24, select: { id: true, templateId: true },
  });
  if (!kept.length) throw new FactoryError(400, wanted.length ? "Ces visuels n'appartiennent pas à cette fabrique." : "Gardez d'abord des visuels (bouton « Garder ») : les variations partent des gardées.");
  if (!input.persona && !input.season && !(input.instructions ?? "").trim()) throw new FactoryError(400, "Dites ce qui change : une persona, une saison ou une consigne.");
  const parentAssets: Record<string, string[]> = {};
  for (const a of kept) (parentAssets[a.templateId!] ??= []).push(a.id);
  const templates = (await loadRunTemplates(Object.keys(parentAssets))).filter((t) => !!t.file);
  if (!templates.length) throw new FactoryError(400, "Les templates de ces visuels n'ont plus d'image.");
  const parentSettings = parseSettings(parent.settingsJson);
  const perTemplate = Math.min(6, Math.max(1, Math.round(input.perTemplate ?? 2)));
  const instructions = [input.instructions?.trim(), parentSettings.instructions ? `(consignes de la fabrique d'origine : ${parentSettings.instructions})` : ""].filter(Boolean).join(" ").slice(0, 1500);
  const settings: FactorySettings = { n: 0, engine: parentSettings.engine, ratio: parentSettings.ratio, textless: parentSettings.textless, perTemplate, attempted: 0, failed: 0, parentAssets, ...(input.persona ? { persona: input.persona.slice(0, 200) } : {}), ...(input.season ? { season: input.season.slice(0, 200) } : {}), ...(instructions ? { instructions } : {}) };
  // The parent's frozen context, then what this variation asks.
  const what = [input.persona ? `Persona visée : ${input.persona}` : "", input.season ? `Saison / moment : ${input.season}` : "", input.instructions?.trim() ? `Consigne : ${input.instructions.trim()}` : ""].filter(Boolean).join("\n");
  const contextMd = `${parent.contextMd}\n\n## Variation demandée (${kept.length} visuel${kept.length > 1 ? "s" : ""} gardé${kept.length > 1 ? "s" : ""} de la fabrique du ${parent.createdAt.toLocaleDateString("fr-FR")})\n${what}`;
  const row = await prisma.factoryRun.create({ data: {
    alertClientId: client.id, clientName: client.name, kind: "variation", status: "draft", parentRunId: parent.id, templateIdsJson: JSON.stringify(templates.map((t) => t.id)),
    contextMd, sourcesJson: JSON.stringify([...parseSources(parent.sourcesJson), { kind: "instructions", ref: "variation", chars: what.length }]), settingsJson: JSON.stringify(settings), createdById: user.id, createdByName: user.name,
  } });
  const { copies, error } = await proposeCopies(row, templates, user);
  const updated = await prisma.factoryRun.update({ where: { id: row.id }, data: { status: "copy_review", ...(error ? { settingsJson: JSON.stringify({ ...settings, error }) } : {}) } });
  return { run: runView(updated, copies), templates, ...(error ? { error } : {}) };
}

/** Sonnet (low, no tool) writes the copies; the rows replace the proposals not yet approved. */
export async function proposeCopies(run: FactoryRun, templates: CreativeTemplate[], user: FactoryUser): Promise<{ copies: FactoryCopy[]; error?: string }> {
  const settings = parseSettings(run.settingsJson);
  // What the consultant said about this batch (« Reproposer » with a feedback), and for a variation the kept visuals to decline.
  const runFeedback = feedbackLines(await prisma.creativeFeedback.findMany({ where: { runId: { in: [run.id, ...(run.parentRunId ? [run.parentRunId] : [])] }, level: "run" }, orderBy: { createdAt: "desc" }, take: 12, select: { text: true } }));
  const keptCopies = settings.parentAssets ? await keptCopiesOf(settings.parentAssets, templates) : [];
  const { system, user: prompt } = buildCopyProposalPrompt({ clientName: run.clientName, kind: run.kind as FactoryKind, contextMd: run.contextMd, templates: templates.map(templateInput), perTemplate: settings.perTemplate, persona: settings.persona, season: settings.season, feedback: runFeedback, kept: keptCopies });
  let proposals: ReturnType<typeof parseCopyProposals> = [];
  let error: string | undefined;
  try {
    const text = await relayComplete(
      { messages: [{ role: "user", content: prompt }], systemPrompt: system, allowedServers: [], accountScope: {}, model: MODEL, effort: "low", maxTurns: 1 },
      { maxMs: 150_000, onUsage: (usage) => void recordAiUsage(usage, { feature: "creas_copy", clientName: run.clientName, user: { id: user.id, email: user.email, role: user.role } }) },
    );
    proposals = parseCopyProposals(parseLooseJson<unknown>(text), templates, settings.perTemplate);
    if (!proposals.length) error = "Le modèle n'a renvoyé aucune proposition lisible : réessayez (« Reproposer »).";
  } catch (e) {
    error = `Propositions de copy impossibles : ${e instanceof Error ? e.message : String(e)}`;
    console.error("[fabrique] copy", error);
  }
  await prisma.factoryCopy.deleteMany({ where: { runId: run.id, status: { not: "approved" } } });
  const kept = await prisma.factoryCopy.count({ where: { runId: run.id } });
  for (const [i, p] of proposals.entries()) {
    await prisma.factoryCopy.create({ data: { runId: run.id, templateId: p.templateId, order: kept + i, headline: p.headline, subline: p.subline, cta: p.cta, angle: p.angle, persona: p.persona, voiceSource: p.voiceSource } });
  }
  return { copies: await runCopies(run.id), ...(error ? { error } : {}) };
}

/** The copies behind the kept visuals of a parent run, numbered by template (T1, T2… of the variation run). */
async function keptCopiesOf(parentAssets: Record<string, string[]>, templates: CreativeTemplate[]): Promise<Array<{ template: number; headline: string; subline: string; cta: string }>> {
  const ids = Object.values(parentAssets).flat();
  const assets = await prisma.creativeAsset.findMany({ where: { id: { in: ids } }, select: { templateId: true, copyId: true, prompt: true } });
  const copies = await prisma.factoryCopy.findMany({ where: { id: { in: assets.map((a) => a.copyId).filter((x): x is string => !!x) } } });
  const byId = new Map(copies.map((c) => [c.id, c]));
  const index = new Map(templates.map((t, i) => [t.id, i + 1]));
  return assets.map((a) => { const c = a.copyId ? byId.get(a.copyId) : null; return { template: index.get(a.templateId ?? "") ?? 0, headline: c?.headline ?? a.prompt.split(" — ")[0], subline: c?.subline ?? "", cta: c?.cta ?? "" }; }).filter((k) => k.template > 0 && k.headline).slice(0, 24);
}

// ── Validate the copies ────────────────────────────────────────────────────

export interface CopyPatch { id: string; status?: "approved" | "rejected" | "proposed"; headline?: string; subline?: string; cta?: string }

export async function updateCopies(run: FactoryRun, patches: CopyPatch[]): Promise<FactoryCopy[]> {
  if (!canTransition(run.status as RunStatus, "copy_review") && run.status !== "copy_review") throw new FactoryError(409, "Les copys de cette fabrique ne se modifient plus (génération lancée).");
  const mine = new Set((await prisma.factoryCopy.findMany({ where: { runId: run.id }, select: { id: true } })).map((c) => c.id));
  for (const p of patches) {
    if (!mine.has(p.id)) continue;
    const data: Partial<Pick<FactoryCopy, "status" | "headline" | "subline" | "cta" | "editedByHuman">> = {};
    if (p.status) data.status = p.status;
    const txt = (v: unknown, max: number) => (typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : undefined);
    const headline = txt(p.headline, 120); const subline = txt(p.subline, 200); const cta = txt(p.cta, 40);
    if (headline) { data.headline = headline; data.editedByHuman = true; }
    if (subline !== undefined) { data.subline = subline; data.editedByHuman = true; }
    if (cta !== undefined) { data.cta = cta; data.editedByHuman = true; }
    if (Object.keys(data).length) await prisma.factoryCopy.update({ where: { id: p.id }, data });
  }
  return runCopies(run.id);
}

// ── Generate by passes ─────────────────────────────────────────────────────

export class FactoryError extends Error { constructor(public status: number, message: string) { super(message); } }

export interface GenerateOptions { n?: number; engine?: string; ratio?: string; textless?: boolean }
export interface PassResult { run: FactoryRunView; assets: AssetView[]; remaining: number; failed: number; warn?: string }

async function unitPrice(engine: string): Promise<number> {
  try { return (await relayFalModels()).models.find((m) => m.id === engine)?.usd ?? 0; } catch { return 0; }
}

/**
 * One pass of ≤ PASS_SIZE images. The first call (run in copy_review /
 * approved) takes the settings (n, engine, ratio), checks the quota on the
 * whole run and moves it to « generating »; each pass checks the quota on
 * its own size. A failed batch counts its visuals as missing and never
 * kills the run. Returns what remains so the browser calls again.
 */
export async function generatePass(run: FactoryRun, client: FactoryClient, user: FactoryUser, opts: GenerateOptions): Promise<PassResult> {
  let settings = parseSettings(run.settingsJson);
  const status = run.status as RunStatus;
  const copies = await runCopies(run.id);
  const approved = copies.filter((c) => c.status === "approved");
  if (!approved.length) throw new FactoryError(400, "Validez au moins un copy avant de générer.");
  const starting = status === "copy_review" || status === "approved" || (status === "failed" && settings.attempted === 0);
  if (starting) {
    const n = Math.round(Number(opts.n));
    if (!Number.isFinite(n) || n < 1) throw new FactoryError(400, "Indiquez le nombre de visuels à générer.");
    if (n > MAX_RUN_IMAGES) throw new FactoryError(400, `Au plus ${MAX_RUN_IMAGES} visuels par fabrique pour l'instant.`);
    settings = { ...settings, n, engine: isFalModel(opts.engine) ? opts.engine : DEFAULT_FACTORY_ENGINE, ratio: (IMAGE_RATIOS as readonly string[]).includes(String(opts.ratio)) ? String(opts.ratio) : "1:1", textless: opts.textless === true, attempted: 0, failed: 0 };
    delete settings.error;
  } else if (status !== "generating") throw new FactoryError(409, `Cette fabrique est « ${status} » : rien à générer.`);
  const remainingBefore = remainingOf(settings);
  if (remainingBefore <= 0) return { run: runView(await finishRun(run.id, settings), copies), assets: [], remaining: 0, failed: 0 };

  // Price and caps: the whole run when it starts, this pass afterwards.
  const unit = await unitPrice(settings.engine);
  const passCount = Math.min(PASS_SIZE, remainingBefore);
  const gate = checkGeneration(await readQuotas(), await spentToday(user.id), estimateUsd(unit, starting ? settings.n : passCount), starting ? settings.n : passCount);
  if (!gate.ok) throw new FactoryError(429, gate.reason ?? "Plafond atteint.");
  if (starting) run = await prisma.factoryRun.update({ where: { id: run.id }, data: { status: "generating", estimatedUsd: estimateUsd(unit, settings.n), settingsJson: JSON.stringify(settings) } });

  // References per template: its picture, then ≤ 2 brand assets of the client.
  const templates = await loadRunTemplates(parseIdList(run.templateIdsJson));
  const byTemplate = new Map(templates.map((t) => [t.id, t]));
  const brandRows = await prisma.creativeAsset.findMany({ where: { alertClientId: client.id, origin: "asset", status: "completed", deletedAt: null, file: { not: null } }, orderBy: { createdAt: "desc" }, take: 2, select: { file: true } });
  const brandRefs = (await Promise.all(brandRows.map((r) => (r.file ? mediaFileDataUri(r.file) : null)))).filter((x): x is string => !!x);
  const templateRefs = new Map<string, string>();
  for (const t of templates) { const uri = t.file ? await mediaFileDataUri(t.file) : null; if (uri) templateRefs.set(t.id, uri); }
  // What the consultants said about each template (template-level feedback, notes of cut visuals): written as « à éviter » in the image prompt.
  const avoidBy = new Map<string, string[]>();
  const [tplFeedback, cutNotes] = await Promise.all([
    prisma.creativeFeedback.findMany({ where: { templateId: { in: templates.map((t) => t.id) }, level: "template" }, orderBy: { createdAt: "desc" }, take: 40, select: { templateId: true, text: true } }),
    prisma.creativeAsset.findMany({ where: { templateId: { in: templates.map((t) => t.id) }, feedback: "cut", feedbackNote: { not: null }, deletedAt: null }, orderBy: { updatedAt: "desc" }, take: 40, select: { templateId: true, feedbackNote: true } }),
  ]);
  for (const t of templates) avoidBy.set(t.id, feedbackLines([...tplFeedback.filter((f) => f.templateId === t.id), ...cutNotes.filter((c) => c.templateId === t.id).map((c) => ({ text: c.feedbackNote ?? "" }))], 4));
  // A variation: the kept visual of the parent run comes first among the references.
  const parentRefs = new Map<string, string>();
  for (const id of Object.values(settings.parentAssets ?? {}).flat()) {
    const a = await prisma.creativeAsset.findUnique({ where: { id }, select: { file: true } });
    const uri = a?.file ? await mediaFileDataUri(a.file) : null;
    if (uri) parentRefs.set(id, uri);
  }

  const plan = passPlan(planSlots(approved, settings.n), settings.attempted);
  const copyById = new Map(copies.map((c) => [c.id, c]));
  const created: CreativeAsset[] = [];
  let failed = 0;
  let lastError: string | undefined;
  let batchNo = 0;
  const runBatch = async (b: (typeof plan)[number]) => {
    const t = byTemplate.get(b.templateId); const c = copyById.get(b.copyId); const ref = t && templateRefs.get(t.id);
    if (!t || !c || !ref) { failed += b.count; lastError = "template sans image exploitable"; return; }
    const analysis = parseAnalysis(t.analysisJson);
    const parentId = variationReference(settings.parentAssets, t.id, batchNo++);
    const parentRef = parentId ? parentRefs.get(parentId) : undefined;
    const refs = [...(parentRef ? [parentRef] : []), ref, ...brandRefs].slice(0, 3);
    const prompt = buildFactoryImagePrompt(buildCopyPrompt({ template: t, analysis, clientName: client.name, instructions: settings.instructions ?? "", assets: refs.length - 1, textless: settings.textless }), c, settings.textless, avoidBy.get(t.id) ?? [], !!parentRef);
    try {
      const out = await relayFalImage({ prompt, model: settings.engine, ratio: settings.ratio, images: refs, n: b.count });
      const paramsJson = JSON.stringify({ ratio: settings.ratio, engine: settings.engine, references: refs.length, mode: "edit", textless: settings.textless, promptSent: prompt, group: `f_${run.id.slice(-6)}`, variants: b.count, templateId: t.id, templateName: t.name, factoryRunId: run.id, copyId: c.id, headline: c.headline });
      for (const [i, url] of out.urls.entries()) {
        created.push(await prisma.creativeAsset.create({ data: {
          createdById: user.id, createdByName: user.name, alertClientId: client.id, clientName: client.name, prompt: `${c.headline}${c.subline ? ` — ${c.subline}` : ""}`.slice(0, 300),
          kind: "image", model: out.model, paramsJson, status: "completed", progress: 100, url, file: out.files[i] ?? null, costUsd: out.usd / Math.max(1, out.urls.length),
          templateId: t.id, origin: "factory", factoryRunId: run.id, copyId: c.id,
        } }));
      }
      if (out.urls.length < b.count) failed += b.count - out.urls.length;
    } catch (e) {
      failed += b.count; lastError = e instanceof Error ? e.message : String(e);
      console.error("[fabrique] paquet en échec", run.id, lastError);
    }
  };
  // Up to PARALLEL_BATCHES fal calls at a time.
  const queue = [...plan];
  await Promise.all(Array.from({ length: Math.min(PARALLEL_BATCHES, queue.length) }, async () => { for (let b = queue.shift(); b; b = queue.shift()) await runBatch(b); }));

  const attemptedNow = plan.reduce((s, b) => s + b.count, 0);
  settings = { ...settings, attempted: settings.attempted + attemptedNow, failed: settings.failed + failed, ...(lastError ? { error: `Dernier échec : ${lastError.slice(0, 300)}` } : {}) };
  if (!lastError) delete settings.error;

  // Drive: the run's folder under the client's « Créas », one file per visual (best effort).
  let drive: { folderId: string | null; link: string | null } = { folderId: run.driveFolderId, link: run.driveLink };
  const driveWarn = await copyToDrive(run, client, templates, copyById, created, drive).then((d) => { drive = d.drive; return d.warn; });

  const updated = await finishRun(run.id, settings, drive);
  const warn = [gate.warn, driveWarn, failed ? `${failed} visuel${failed > 1 ? "s" : ""} en échec sur ce passage${lastError ? ` (${lastError.slice(0, 160)})` : ""}.` : ""].filter(Boolean).join(" ") || undefined;
  return { run: runView(updated, copies), assets: created.map((a) => assetView(a, user.id)), remaining: remainingOf(settings), failed, ...(warn ? { warn } : {}) };
}

/** Counters and status of a run from its assets (generated, cost = sum of the assets' costUsd). */
async function finishRun(runId: string, settings: FactorySettings, drive?: { folderId: string | null; link: string | null }): Promise<FactoryRun> {
  const agg = await prisma.creativeAsset.aggregate({ where: { factoryRunId: runId, deletedAt: null, status: "completed" }, _count: { _all: true }, _sum: { costUsd: true } });
  const verdicts = await prisma.creativeAsset.groupBy({ by: ["feedback"], where: { factoryRunId: runId, deletedAt: null }, _count: { _all: true } });
  const kept = verdicts.find((v) => v.feedback === "keep")?._count._all ?? 0;
  const cut = verdicts.find((v) => v.feedback === "cut")?._count._all ?? 0;
  const status = statusAfterPass(settings);
  return prisma.factoryRun.update({ where: { id: runId }, data: {
    settingsJson: JSON.stringify(settings), generated: agg._count._all, costUsd: Math.round((agg._sum.costUsd ?? 0) * 1000) / 1000, kept, cut, status,
    ...(status === "review" ? { deliveredAt: new Date() } : {}), ...(drive ? { driveFolderId: drive.folderId, driveLink: drive.link } : {}),
  } });
}

async function copyToDrive(run: FactoryRun, client: FactoryClient, templates: CreativeTemplate[], copyById: Map<string, FactoryCopy>, created: CreativeAsset[], drive: { folderId: string | null; link: string | null }): Promise<{ drive: { folderId: string | null; link: string | null }; warn?: string }> {
  if (!created.length) return { drive };
  try {
    if (!drive.folderId) {
      const dashboardId = (await clientDashboardIds(client))[0];
      if (!dashboardId) return { drive, warn: "Pas de dossier Drive : ce client n'a pas de dashboard (les visuels restent dans ImpulseMotion)." };
      const creas = await ensureClientSubfolder(dashboardId, "creas");
      if (!creas) return { drive, warn: "Pas de dossier Drive pour ce client." };
      const folder = await ensureSubfolder(creas.id, factoryFolderName(run.kind as FactoryKind, run.createdAt), `Fabrique de statics ImpulseMotion du ${run.createdAt.toLocaleDateString("fr-FR")} (${run.kind}) pour ${client.name}.`);
      drive = { folderId: folder.id, link: folder.webViewLink ?? `https://drive.google.com/drive/folders/${folder.id}` };
    }
    const folderId = drive.folderId!;
    const names = new Map(templates.map((t) => [t.id, t.name]));
    const base = await prisma.creativeAsset.count({ where: { factoryRunId: run.id, deletedAt: null, id: { notIn: created.map((a) => a.id) } } });
    const results = await Promise.allSettled(created.map(async (a, i) => {
      const uri = a.file ? await mediaFileDataUri(a.file) : null;
      if (!uri) throw new Error("fichier absent du relay");
      const m = uri.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
      if (!m) throw new Error("image illisible");
      const ext = m[1] === "image/png" ? "png" : m[1] === "image/webp" ? "webp" : "jpg";
      await uploadToFolder(folderId, { name: factoryFileName(base + i, names.get(a.templateId ?? "") ?? "template", copyById.get(a.copyId ?? "")?.headline ?? "", ext), mimeType: m[1], data: Buffer.from(m[2], "base64") });
    }));
    const lost = results.filter((r) => r.status === "rejected").length;
    return { drive, ...(lost ? { warn: `${lost} fichier${lost > 1 ? "s" : ""} non copié${lost > 1 ? "s" : ""} dans Drive.` } : {}) };
  } catch (e) {
    return { drive, warn: `Drive indisponible : ${e instanceof Error ? e.message : String(e)}` };
  }
}

// ── Feedback at three levels ───────────────────────────────────────────────

export interface FeedbackInput { level: FeedbackLevel; text: string; assetId?: string | null; templateId?: string | null; runId?: string | null }

/**
 * A consultant's feedback on a visual, a template, a run or the client:
 * stored, and journaled in the client's HQ project (one entry per run,
 * slug fabrique-<runId>) — the UI says so before the click.
 */
export async function addFeedback(client: FactoryClient, user: FactoryUser, input: FeedbackInput): Promise<{ feedback: FeedbackView; hq: { ok: boolean; error?: string } }> {
  const text = input.text.replace(/\s+/g, " ").trim().slice(0, 2000);
  if (text.length < 3) throw new FactoryError(400, "Écrivez votre retour.");
  const run = input.runId && RUN_ID_RE.test(input.runId) ? await prisma.factoryRun.findUnique({ where: { id: input.runId } }) : null;
  const template = input.templateId && RUN_ID_RE.test(input.templateId) ? await prisma.creativeTemplate.findUnique({ where: { id: input.templateId }, select: { id: true, name: true } }) : null;
  const asset = input.assetId && RUN_ID_RE.test(input.assetId) ? await prisma.creativeAsset.findUnique({ where: { id: input.assetId }, select: { id: true, prompt: true } }) : null;
  if (input.level === "template" && !template) throw new FactoryError(404, "Template introuvable.");
  if (input.level === "run" && !run) throw new FactoryError(404, "Fabrique introuvable.");
  if (input.level === "asset" && !asset) throw new FactoryError(404, "Visuel introuvable.");
  const row = await prisma.creativeFeedback.create({ data: { level: input.level, alertClientId: client.id, assetId: asset?.id ?? null, templateId: template?.id ?? null, runId: run?.id ?? null, text, createdById: user.id, createdByName: user.name } });

  let hq: { ok: boolean; error?: string } = { ok: false, error: "Ce client n'a pas de dossier HQ rattaché : le retour reste dans ImpulseMotion." };
  const project = await clientHqProject(client);
  if (project) {
    const date = new Date().toLocaleDateString("fr-FR", { timeZone: "Europe/Paris" });
    const about = input.level === "asset" ? `la pub « ${asset!.prompt.slice(0, 100)} »` : input.level === "template" ? `le template « ${template!.name} »` : input.level === "run" ? `la fabrique du ${run!.createdAt.toLocaleDateString("fr-FR")} (${run!.kind})` : "le client";
    const content = [
      `## Retour fabrique de statics — ${date}`,
      `- Sur ${about}${run && input.level !== "run" ? ` (fabrique ${run.id.slice(-8)})` : ""}`,
      `- Retour de ${user.name} : ${text}`,
      `- Lien : /creas?client=${client.id}&tab=fabrique${run ? `&run=${run.id}` : template ? `&template=${template.id}` : ""}`,
    ].join("\n");
    const slug = run ? `fabrique-${run.id}` : template ? `template-${template.id.slice(-8)}` : asset ? `crea-${asset.id.slice(-8)}` : `client-${client.id.slice(-8)}`;
    hq = await appendHqJournal({ project, slug, content }).catch((e) => ({ ok: false, error: e instanceof Error ? e.message : String(e) }));
  }
  return { feedback: feedbackView(row), hq };
}

export async function listFeedback(where: { templateId?: string; runId?: string; assetId?: string; clientId?: string }, take = 50): Promise<FeedbackView[]> {
  const rows = await prisma.creativeFeedback.findMany({ where: { ...(where.templateId ? { templateId: where.templateId } : {}), ...(where.runId ? { runId: where.runId } : {}), ...(where.assetId ? { assetId: where.assetId } : {}), ...(where.clientId ? { alertClientId: where.clientId } : {}) }, orderBy: { createdAt: "desc" }, take });
  return rows.map(feedbackView);
}
